SCHEMA = fastavro.parse_schema({
    "type": "record", "name": "Reading",
    "fields": [
        {"name": "sensor_id", "type": "long"},
        {"name": "celsius", "type": "int"},
        {"name": "room", "type": "string"},
    ],
})

def save(db, reading):
    buf = io.BytesIO()
    fastavro.schemaless_writer(buf, SCHEMA, reading)
    db.insert("readings", buf.getvalue())

def load(db, row_id):
    raw = db.get("readings", row_id)
    return fastavro.schemaless_reader(io.BytesIO(raw), SCHEMA)
